//! The catalogued k2web boards (#80): one row each, from the census of the
//! active boards (2026-11-23). Columns: source ID, display name, page title
//! (the list page's `<title>`), organization, settings group, site, menu, bbs,
//! regular rows per page, skin. A board seen with only one page has the page
//! size of another board of its site, else 10; the pager check fails loudly
//! if that guess is wrong once the board grows.
use super::{K2webBoard, Skin};

#[allow(clippy::too_many_arguments)]
const fn board(
    source_id: &'static str,
    name: &'static str,
    title: &'static str,
    organization: &'static str,
    group: &'static str,
    site: &'static str,
    menu: u32,
    bbs: u32,
    rows: u32,
    skin: Skin,
) -> K2webBoard {
    K2webBoard {
        source_id,
        name,
        title,
        organization,
        group,
        site,
        menu,
        bbs,
        rows,
        skin,
    }
}

